{
  "apiVersion": 1,
  "type": "help",
  "data": {
    "command": "astryx integration check",
    "description": "The CI check for an integration package's own build: every source check, run in continuous integration or a typecheck script, against the package in the current folder",
    "usage": "astryx integration check [options]",
    "options": [
      {
        "flags": "--strict",
        "description": "Also exit 1 on any warning and on any check that did not run. A new check or failure code joins only in a minor release, named in the release notes; until then, a malformed `cliCommand` is reported as a note (`invalid_cli_command`) that fails nothing."
      },
      {
        "flags": "--next",
        "description": "Also count the findings the next minor release turns into warnings (the notes marked `next`) as warnings now, so `--strict --next` fails on them. Run it to fix them ahead of the release; every run says how many there are."
      }
    ],
    "subcommands": []
  },
